datadog:aws/integrationAccount:Integrati.description:
Provides a Datadog—Amazon Web Services integration resource. This can be used to create and manage Datadog—Amazon Web Services integration.

## Example Usage

<!--Start PulumiCodeChooser -->
```typescript
import * as pulumi from "@pulumi/pulumi";
import * as datadog from "@pulumi/datadog";

// Create new integration_aws_account resource
const foo = new datadog.aws.IntegrationAccount("foo", {
    accountTags: ["env:prod"],
    awsAccountId: "123456789012",
    awsPartition: "aws",
    awsRegions: [{
        includeAll: true,
    }],
    authConfig: [{
        awsAuthConfigRole: [{
            roleName: "DatadogIntegrationRole",
        }],
    }],
    logsConfig: [{
        lambdaForwarder: [{
            lambdas: ["arn:aws:lambda:us-east-1:123456789012:function:my-lambda"],
            sources: ["s3"],
            logSourceConfig: [{
                tagFilters: [{
                    source: "s3",
                    tags: [
                        "env:prod",
                        "team:backend",
                    ],
                }],
            }],
        }],
    }],
    metricsConfig: [{
        automuteEnabled: true,
        collectCloudwatchAlarms: true,
        collectCustomMetrics: true,
        enabled: true,
        namespaceFilters: [{
            excludeOnlies: [
                "AWS/SQS",
                "AWS/ElasticMapReduce",
                "AWS/Usage",
            ],
        }],
        metricNameFilters: [
            {
                namespace: "AWS/EC2",
                includeOnlies: ["aws.ec2.network_in"],
            },
            {
                namespace: "AWS/RDS",
                excludeOnlies: ["aws.rds.aurora*"],
            },
        ],
        tagFilters: [{
            namespace: "AWS/EC2",
            tags: ["datadog:true"],
        }],
    }],
    resourcesConfig: [{
        cloudSecurityPostureManagementCollection: true,
        extendedCollection: true,
    }],
    tracesConfig: [{
        xrayServices: [{
            includeAll: true,
        }],
    }],
});
// Create new integration_aws_account resource with all Datadog-provided defaults configured
