# Example Usage (Synthetics Browser test)
# Create a new Datadog Synthetics Browser test starting on https://www.example.org
resource "datadog_syntheticstest" "test_browser" {
  name       = "A Browser test on example.org"
  type       = "browser"
  status     = "paused"
  message    = "Notify @qa"
  device_ids = ["laptop_large"]
  locations  = ["aws:eu-central-1"]
  tags       = []
  request_definition = {
    method = "GET"
    url    = "https://www.example.org"
  }
  browser_steps {
    name = "Check current url"
    type = "assertCurrentUrl"
    params = {
      check = "contains"
      value = "datadoghq"
    }
  }
  browser_steps {
    name = "Test a downloaded file"
    type = "assertFileDownload"
    params = {
      file = jsonencode({
        "md5" = "abcdef1234567890"
        "sizeCheck" = {
          "type"  = "equals"
          "value" = 1
        }
        "nameCheck" = {
          "type"  = "contains"
          "value" = ".xls"
        }
      })
    }
  }
  browser_steps {
    name = "Upload a file"
    type = "uploadFiles"
    params = {
      files = jsonencode([{
        "name"    = "hello.txt"
        "size"    = 11
        "content" = "Hello world"
      }])
      element_user_locator = {
        value = {
          type  = "css"
          value = "#simple-file-upload"
        }
      }
      element = jsonencode({
        "userLocator" = {
          "failTestOnCannotLocate" = true
          "values" = [{
            "type"  = "css"
            "value" = "#simple-file-upload"
          }]
        }
      })
    }
  }
  browser_steps {
    name = "Test sending http requests"
    type = "assertRequests"
    params = {
      requests = jsonencode({
        "count" = {
          "type"  = "equals"
          "value" = 1
        }
        "url" = "https://www.example.org"
      })
    }
  }
  browser_steps {
    name = "Run api test"
    type = "runApiTest"
    params = {
      request = jsonencode({
        "config" = {
          "assertions" = [{
            "type"     = "statusCode"
            "operator" = "is"
            "target"   = 200
          }]
          "request" = {
            "method" = "GET"
            "url"    = "https://example.com"
          }
        }
        "options" = {}
        "subtype" = "http"
      })
    }
  }
  browser_steps {
    name = "Drag element to target"
    type = "drag"
    params = {
      element_user_locator = {
        value = {
          type  = "css"
          value = "#drag-source"
        }
      }
      drag_drop_options = {
        delay = 120
        offset = {
          x = 100
          y = 100
        }
      }
    }
  }
  browser_steps {
    name = "Drop on target"
    type = "drop"
    params = {
      element_user_locator = {
        value = {
          type  = "css"
          value = "#drop-target"
        }
      }
      drag_drop_options = {
        delay = 100
      }
    }
  }
  // min   = 1      // only used for "between"
  // max   = 1      // only used for "between"
  // Size of the file in bytes
  // min   = 1      // only used for "between"
  // max   = 1      // only used for "between"
  browser_variables {
    type    = "text"
    name    = "MY_PATTERN_VAR"
    pattern = "{{numeric(3)}}"
    example = "597"
  }
  browser_variables {
    type    = "email"
    name    = "MY_EMAIL_VAR"
    pattern = "jd8-afe-ydv.{{ numeric(10) }}@synthetics.dtdg.co"
    example = "jd8-afe-ydv.4546132139@synthetics.dtdg.co"
  }
  browser_variables {
    type = "global"
    name = "MY_GLOBAL_VAR"
    id   = "76636cd1-82e2-4aeb-9cfe-51366a8198a2"
  }
  options_list = {
    tick_every = 3600
  }
}
