    name: "Complete Tag Pipeline Example",
    enabled: true,
    rules: [
        {
            name: "standardize-environment",
            enabled: true,
            mapping: [{
                destinationKey: "env",
                ifTagExists: "replace",
                sourceKeys: [
                    "environment",
                    "stage",
                    "tier",
                ],
            }],
        },
        {
            name: "assign-team-tags",
            enabled: true,
            query: [{
                query: "service:web* OR service:frontend*",
                caseInsensitivity: true,
                ifTagExists: "append",
                addition: [{
                    key: "team",
                    value: "frontend",
                }],
            }],
        },
        {
            name: "enrich-service-metadata",
            enabled: true,
            referenceTable: [{
                tableName: "service_catalog",
                caseInsensitivity: true,
                ifTagExists: "append",
                sourceKeys: ["service"],
                fieldPairs: [
                    {
                        inputColumn: "owner_team",
                        outputKey: "owner",
                    },
                    {
                        inputColumn: "business_unit",
                        outputKey: "business_unit",
                    },
                ],
            }],
        },
    ],
});
