datadog:index/workflowAutomation:Workflo.description:
Enables the creation and management of Datadog workflows using Workflow Automation. To easily export a workflow for use with Terraform, use the export button in the Datadog Workflow Automation UI. This resource requires a registered application key.

## Example Usage

<!--Start PulumiCodeChooser -->
```typescript
import * as pulumi from "@pulumi/pulumi";
import * as datadog from "@pulumi/datadog";

const workflow = new datadog.WorkflowAutomation("workflow", {
    name: "Send Email when Monitor Alerts",
    description: "This workflow alerts me by email when my monitor goes off. ",
    tags: [
        "service:foo",
        "source:alert",
        "team:bar",
    ],
    published: true,
    specJson: JSON.stringify({
        triggers: [{
            startStepNames: ["Send_Email"],
            monitorTrigger: {},
        }],
        steps: [{
            name: "Send_Email",
            actionId: "com.datadoghq.email.send",
            parameters: [
                {
                    name: "to",
                    value: "REPLACE_ME",
                },
                {
                    name: "subject",
                    value: "Monitor \"{{ Source.monitor.name }}\" alerted",
                },
                {
                    name: "message",
                    value: `This message is from {{ WorkflowName }}. 

You can find a link to the monitor here: {{ Source.url }}.`,
                },
            ],
            display: {
                bounds: {
                    x: 0,
                    y: 216,
                },
            },
        }],
        handle: "my-handle",
    }),
});
